// config/secrets.js
const { SecretsManagerClient, GetSecretValueCommand } = require('@aws-sdk/client-secrets-manager');

const secretsClient = new SecretsManagerClient({
  region: process.env.AWS_REGION || 'us-east-1'
});

let secretsCache = null;
let cacheExpiry = null;

async function getSecret(secretName, forceRefresh = false) {
  // Cache secrets for 5 minutes
  if (!forceRefresh && secretsCache && cacheExpiry > Date.now()) {
    return secretsCache[secretName];
  }

  try {
    const response = await secretsClient.send(
      new GetSecretValueCommand({
        SecretId: secretName,
        VersionStage: 'AWSCURRENT'
      })
    );

    const secretData = JSON.parse(response.SecretString);

    // Update cache
    secretsCache = { ...secretsCache, ...secretData };
    cacheExpiry = Date.now() + (5 * 60 * 1000); // 5 minutes

    return secretData[secretName];
  } catch (error) {
    console.error(`Error retrieving secret ${secretName}:`, error);
    throw new Error('Failed to retrieve secrets');
  }
}

// Load all secrets at startup
async function loadAllSecrets(secretNames) {
  const secrets = {};
  for (const name of secretNames) {
    try {
      secrets[name] = await getSecret(name);
    } catch (error) {
      console.error(`Failed to load secret: ${name}`);
      throw error;
    }
  }
  return secrets;
}

module.exports = { getSecret, loadAllSecrets };
```

