// config/secrets.js
const AWS = require('aws-sdk');

class SecretsManager {
  constructor() {
    this.client = new AWS.SecretsManager({
      region: process.env.AWS_REGION || 'us-east-1'
    });
    this.cache = {};
    this.cacheTTL = 5 * 60 * 1000; // 5 minutes
  }

  async getSecret(secretName, forceRefresh = false) {
    // Check cache first
    if (!forceRefresh && this.cache[secretName]) {
      const cached = this.cache[secretName];
      if (Date.now() - cached.timestamp < this.cacheTTL) {
        return cached.value;
      }
    }

    try {
      const data = await this.client.getSecretValue({
        SecretId: secretName
      }).promise();

      let secret;
      if ('SecretString' in data) {
        secret = JSON.parse(data.SecretString);
      } else {
        secret = Buffer.from(data.SecretBinary, 'base64').toString('ascii');
      }

      // Cache the result
      this.cache[secretName] = {
        value: secret,
        timestamp: Date.now()
      };

      return secret;
    } catch (error) {
      console.error(`Failed to retrieve secret ${secretName}:`, error.message);
      throw new Error(`Secret retrieval failed: ${secretName}`);
    }
  }

  async getDatabaseConfig() {
    return this.getSecret('production/database');
  }

  async getStripeConfig() {
    return this.getSecret('production/stripe');
  }
}

module.exports = new SecretsManager();
