### B. Production-Ready: Secrets Manager Integration

```javascript
// config/secrets-manager.js
const { SecretsManagerClient, GetSecretValueCommand } = require('@aws-sdk/client-secrets-manager');

class SecretsManager {
  constructor() {
    this.client = process.env.NODE_ENV === 'production' 
      ? new SecretsManagerClient({ region: process.env.AWS_REGION || 'us-east-1' })
      : null;

    this.cache = new Map();
    this.cacheTimeout = 5 * 60 * 1000; // 5 minutes
  }

  async getSecret(secretName, forceRefresh = false) {
    // Development/Testing: Use environment variables
    if (process.env.NODE_ENV !== 'production') {
      return process.env[secretName];
    }

    // Production: Check cache first
    if (!forceRefresh && this.cache.has(secretName)) {
      const cached = this.cache.get(secretName);
      if (Date.now() - cached.timestamp < this.cacheTimeout) {
        return cached.value;
      }
    }

    // Fetch from AWS Secrets Manager
    try {
      const command = new GetSecretValueCommand({ SecretId: secretName });
      const response = await this.client.send(command);

      const secretValue = response.SecretString 
        ? JSON.parse(response.SecretString)[secretName] || response.SecretString
        : Buffer.from(response.SecretBinary, 'base64').toString('utf-8');

      // Cache the secret
      this.cache.set(secretName, {
        value: secretValue,
        timestamp: Date.now()
      });

      return secretValue;
    } catch (error) {
      console.error(`Failed to fetch secret ${secretName}:`, error.message);
      throw new Error(`Secret retrieval failed: ${secretName}`);
    }
  }

  async getAllSecrets() {
    const secretNames = [
      'production/database/url',
      'production/jwt/secret',
      'production/stripe/key',
      'production/aws/credentials'
    ];

    const secrets = {};
    for (const name of secretNames) {
      const key = name.split('/').pop();
      secrets[key] = await this.getSecret(name);
    }

    return secrets;
  }

  clearCache(secretName) {
    if (secretName) {
      this.cache.delete(secretName);
    } else {
      this.cache.clear();
    }
  }
}

module.exports = new SecretsManager();
```

