```javascript
// Rotate secrets periodically
class SecretRotator {
  constructor() {
    this.rotationSchedule = {
      JWT_SECRET: '90d',        // Every 90 days
      DATABASE_PASSWORD: '30d', // Every 30 days
      API_KEYS: '60d'           // Every 60 days
    };
  }

  checkRotationNeeded(secretName, lastRotated) {
    const maxAge = this.rotationSchedule[secretName];
    if (!maxAge) return false;

    const age = Date.now() - lastRotated;
    const maxAgeMs = this.parseDuration(maxAge);

    return age > maxAgeMs;
  }

  parseDuration(str) {
    const units = { d: 86400000, h: 3600000, m: 60000, s: 1000 };
    const match = str.match(/^(\d+)([dhms])$/);
    return match ? parseInt(match[1]) * units[match[2]] : 0;
  }
}
