// config/aws-secrets.js
const AWS = require('aws-sdk');
const { SecretsManager } = require('@aws-sdk/client-secrets-manager');

async function getSecret(secretName) {
  const client = new SecretsManager({ region: process.env.AWS_REGION });

  try {
    const response = await client.getSecretValue({ SecretId: secretName });
    return response.SecretString;
  } catch (error) {
    throw new Error(`Failed to retrieve secret ${secretName}: ${error.message}`);
  }
}

async function loadSecrets() {
  const secrets = {
    database: JSON.parse(await getSecret('prod/database/credentials')),
    stripe: JSON.parse(await getSecret('prod/stripe/api')),
    anthropic: JSON.parse(await getSecret('prod/anthropic/api'))
  };

  return secrets;
}

module.exports = { loadSecrets };
```

#### Using AWS Parameter Store
```javascript
// config/aws-ssm.js
const SSM = require('aws-sdk/clients/ssm');
const ssm = new SSM({ region: process.env.AWS_REGION });

async function getParameter(name, withDecryption = true) {
  const result = await ssm.getParameter({
    Name: name,
    WithDecryption: withDecryption
  }).promise();

  return result.Parameter.Value;
}

async function loadParameters() {
  return {
    databaseUrl: await getParameter('/app/database/url'),
    jwtSecret: await getParameter('/app/jwt/secret'),
    stripeKey: await getParameter('/app/stripe/key'),
    anthropicKey: await getParameter('/app/anthropic/key')
  };
}

