/**
 * Secrets Management Module
 *
 * Provides secure access to application secrets from various sources:
 * 1. AWS Secrets Manager (preferred for production)
 * 2. AWS Parameter Store
 * 3. Environment variables (for development)
 */

const AWS = require('@aws-sdk/client-secrets-manager');
const { SSMClient, GetParametersByPathCommand } = require('@aws-sdk/client-ssm');

// Cache configuration
let secretsCache = null;
let cacheExpiry = null;
const DEFAULT_CACHE_TTL = 5 * 60 * 1000; // 5 minutes

/**
 * Get the secrets source based on environment configuration
 */
function getSecretsSource() {
  if (process.env.SECRETS_MANAGER_ARN) {
    return 'aws_secrets_manager';
  }
  if (process.env.PARAMETER_PREFIX) {
    return 'aws_parameter_store';
  }
  return 'environment';
}

/**
 * Load secrets from AWS Secrets Manager
 */
async function loadFromSecretsManager(arn) {
  const client = new AWS.SecretsManagerClient({
    region: process.env.AWS_REGION || 'us-east-1',
  });

  try {
    const response = await client.send(
      new AWS.GetSecretValueCommand({ SecretId: arn })
    );

    if (response.SecretString) {
      return JSON.parse(response.SecretString);
    }

    // Handle binary secrets (not commonly used for app config)
    if (response.SecretBinary) {
      return Buffer.from(response.SecretBinary, 'base64').toString('utf-8');
    }

    throw new Error('Secrets Manager returned neither string nor binary');
  } catch (error) {
    if (error.name === 'ResourceNotFoundException') {
      throw new Error(`Secret not found: ${arn}`);
    }
    if (error.name === 'AccessDeniedException') {
      throw new Error('Access denied to AWS Secrets Manager. Check IAM permissions.');
    }
    throw new Error(`Failed to load secrets from Secrets Manager: ${error.message}`);
  }
}

/**
 * Load secrets from AWS Parameter Store
 */
async function loadFromParameterStore(prefix) {
  const client = new SSMClient({
    region: process.env.AWS_REGION || 'us-east-1',
  });

  try {
    const secrets = {};
    let nextToken = null;

    do {
      const response = await client.send(
        new GetParametersByPathCommand({
          Path: prefix,
          Recursive: true,
          WithDecryption: true,
          NextToken: nextToken,
        })
      );

      response.Parameters.forEach(param => {
        const key = param.Name.replace(prefix, '').replace(/^\//, '');
        secrets[key] = param.Value;
      });

      nextToken = response.NextToken;
    } while (nextToken);

    return secrets;
  } catch (error) {
    if (error.name === 'AccessDeniedException') {
      throw new Error('Access denied to Parameter Store. Check IAM permissions.');
    }
    throw new Error(`Failed to load secrets from Parameter Store: ${error.message}`);
  }
}

/**
 * Load secrets from environment variables
 */
function loadFromEnvironment() {
  const envSecrets = {};

  // Database configuration
  if (process.env.DB_HOST && process.env.DB_NAME) {
    envSecrets.database_url = `postgresql://${process.env.DB_USER}:${process.env.DB_PASSWORD}@${process.env.DB_HOST}:${process.env.DB_PORT || 5432}/${process.env.DB_NAME}`;
  }

  // AWS credentials
  if (process.env.AWS_ACCESS_KEY_ID) {
    envSecrets.aws_access_key_id = process.env.AWS_ACCESS_KEY_ID;
  }
  if (process.env.AWS_SECRET_ACCESS_KEY) {
    envSecrets.aws_secret_access_key = process.env.AWS_SECRET_ACCESS_KEY;
  }

  // Application secrets
  if (process.env.JWT_SECRET) {
    envSecrets.jwt_secret = process.env.JWT_SECRET;
  }
  if (process.env.STRIPE_SECRET_KEY) {
    envSecrets.stripe_secret_key = process.env.STRIPE_SECRET_KEY;
  }
  if (process.env.ANTHROPIC_API_KEY) {
    envSecrets.anthropic_api_key = process.env.ANTHROPIC_API_KEY;
  }

  return envSecrets;
}

/**
 * Get cached secrets or fetch fresh ones
 */
async function getSecrets(fresh = false) {
  // Return cached secrets if available and fresh not requested
  if (!fresh && secretsCache && cacheExpiry && Date.now() < cacheExpiry) {
    return secretsCache;
  }

  const source = getSecretsSource();
  let secrets;

  console.log(`Loading secrets from source: ${source}`);

  try {
    switch (source) {
      case 'aws_secrets_manager':
        secrets = await loadFromSecretsManager(process.env.SECRETS_MANAGER_ARN);
        break;
      case 'aws_parameter_store':
        secrets = await loadFromParameterStore(process.env.PARAMETER_PREFIX);
        break;
      case 'environment':
        secrets = loadFromEnvironment();
        break;
      default:
        throw new Error('Unknown secrets source');
    }

    // Validate that we have some secrets
    if (!secrets || Object.keys(secrets).length === 0) {
      console.warn('⚠️  Warning: No secrets loaded from source:', source);
    }

    // Update cache
    secretsCache = secrets;
    cacheExpiry = Date.now() + (parseInt(process.env.SECRETS_CACHE_TTL) || DEFAULT_CACHE_TTL);

    // Log success (without exposing secret values)
    console.log(`✓ Successfully loaded ${Object.keys(secrets).length} secret(s)`);
    Object.keys(secrets).forEach(key => {
      const isSensitive = /secret|key|password|token/i.test(key);
      console.log(`  - ${key}: ${isSensitive ? '***' : secrets[key]}`);
    });

    return secrets;
  } catch (error) {
    console.error('❌ Failed to load secrets:', error.message);
    throw error;
  }
}

/**
 * Validate that required secrets are present
 */
function validateSecrets(secrets, required) {
