## 🛡️ Secure Implementation Template

```javascript
// config/secrets.js - Centralized secrets management
const { SecretsManagerClient, GetSecretValueCommand } = require('@aws-sdk/client-secrets-manager');
const Joi = require('joi');

const secretsSchema = Joi.object({
  DATABASE_URL: Joi.string().uri().required(),
  JWT_SECRET: Joi.string().min(32).required(),
  STRIPE_SECRET_KEY: Joi.string().pattern(/^sk_(live|test)_/).required(),
  ANTHROPIC_API_KEY: Joi.string().required(),
  LOGFIRE_TOKEN: Joi.string().required(),
  NODE_ENV: Joi.string().valid('development', 'staging', 'production').default('development')
});

class SecretsManager {
  constructor() {
    this.client = new SecretsManagerClient({ region: process.env.AWS_REGION || 'us-east-1' });
    this.cachedSecrets = null;
    this.cacheExpiry = null;
  }

  async loadSecrets() {
    // Check cache (secrets cached for 5 minutes)
    if (this.cachedSecrets && this.cacheExpiry > Date.now()) {
      return this.cachedSecrets;
    }

    try {
      const secretArn = process.env.SECRET_ARN;
      if (!secretArn) {
        throw new Error('SECRET_ARN environment variable not set');
      }

      const response = await this.client.send(
        new GetSecretValueCommand({ SecretId: secretArn })
      );

      const secrets = JSON.parse(response.SecretString);

      // Validate secrets structure
      const { error, value } = secretsSchema.validate(secrets, { abortEarly: false });
      if (error) {
        throw new Error(`Secrets validation failed: ${error.message}`);
      }

      // Cache the validated secrets
      this.cachedSecrets = value;
      this.cacheExpiry = Date.now() + (5 * 60 * 1000); // 5 minutes

      return value;

    } catch (error) {
      console.error('Failed to load secrets:', error);
      throw error;
    }
  }

  async getSecret(key) {
    const secrets = await this.loadSecrets();
    return secrets[key];
  }

  clearCache() {
    this.cachedSecrets = null;
    this.cacheExpiry = null;
  }
}

module.exports = new SecretsManager();
```

