- No filtering/sorting controls (could be abused for data exfiltration)
- No field projection (all fields returned always)
- No rate limiting per endpoint type
- No data minimization principle applied

**Secure design recommendation:**
```javascript
const { query, validationResult } = require('express-validator');

app.get('/users',
  // Validate query parameters with defaults
  query('page').optional().isInt({ min: 1 }).toInt().default(1),
  query('limit').optional().isInt({ min: 1, max: 100 }).toInt().default(20),
  query('fields').optional().matches(/^[a-z,]+$/),
  query('sort').optional().matches(/^-?[a-z]+$/),
  (req, res, next) => {
    const errors = validationResult(req);
    if (!errors.isEmpty()) {
      return res.status(400).json({ errors: errors.array() });
    }
    next();
  },
  async (req, res) => {
    const { page = 1, limit = 20, fields, sort } = req.query;

    // Get all users (in real app, this would query database)
    let users = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ];

    // Apply field projection (data minimization)
    if (fields) {
      const requestedFields = fields.split(',');
      users = users.map(user => {
        const filtered = {};
        requestedFields.forEach(field => {
          if (user.hasOwnProperty(field)) {
            filtered[field] = user[field];
          }
        });
        return filtered;
      });
    }

    // Apply sorting
    if (sort) {
      const field = sort.replace('-', '');
      const direction = sort.startsWith('-') ? -1 : 1;
      users.sort((a, b) => {
        if (a[field] < b[field]) return -1 * direction;
        if (a[field] > b[field]) return 1 * direction;
        return 0;
      });
    }

    // Apply pagination
    const offset = (page - 1) * limit;
    const paginatedUsers = users.slice(offset, offset + limit);

    res.json({
      data: paginatedUsers,
      meta: {
        page,
        limit,
        total: users.length,
        totalPages: Math.ceil(users.length / limit)
      },
      links: {
        self: `/users?page=${page}&limit=${limit}`,
        next: page < Math.ceil(users.length / limit) 
          ? `/users?page=${page + 1}&limit=${limit}` 
          : null,
        prev: page > 1 
          ? `/users?page=${page - 1}&limit=${limit}` 
          : null
      }
    });
  }
);
