const AWS = require('aws-sdk');
const client = new AWS.SecretsManager({ region: process.env.AWS_REGION });

async function loadSecrets() {
  try {
    const response = await client.getSecretValue({
      SecretId: process.env.SECRETS_ARN || 'myapp/production'
    }).promise();

    if ('SecretString' in response) {
      const secrets = JSON.parse(response.SecretString);

      // Set process.env programmatically
      Object.assign(process.env, secrets);

      console.log('✅ Secrets loaded from AWS Secrets Manager');
      return secrets;
    }
  } catch (error) {
    console.error('❌ Failed to load secrets from AWS Secrets Manager:', error.message);
    throw error;
  }
}

// Load secrets before starting server
async function startApp() {
  if (process.env.NODE_ENV === 'production') {
    await loadSecrets();
  }

  // Validate required secrets
  validateSecrets();

  // Start application
  require('./app');
}

startApp().catch(error => {
  console.error('Failed to start application:', error);
  process.exit(1);
});
