// SECURED VERSION OF APP.JS - Security Recommendations Applied

const express = require('express');
const helmet = require('helmet');
const cors = require('cors');
const rateLimit = require('express-rate-limit');
const winston = require('winston');
const { body, validationResult } = require('express-validator');
const morgan = require('morgan');
const compression = require('compression');

const app = express();

// ==================== SECURITY MIDDLEWARE ====================

// Security headers
app.use(helmet({
  contentSecurityPolicy: {
    directives: {
      defaultSrc: ["'self'"],
      styleSrc: ["'self'", "'unsafe-inline'"],
      scriptSrc: ["'self'"],
      imgSrc: ["'self'", "data:"],
    }
  },
  hsts: {
    maxAge: 31536000,
    includeSubDomains: true,
    preload: true
  }
}));

// Hide Express version
app.disable('x-powered-by');

// CORS configuration
const corsOptions = {
  origin: process.env.ALLOWED_ORIGINS?.split(',') || ['http://localhost:3000'],
  credentials: true,
  optionsSuccessStatus: 200,
  methods: ['GET', 'POST', 'PUT', 'DELETE'],
  allowedHeaders: ['Content-Type', 'Authorization']
};
app.use(cors(corsOptions));

// Rate limiting
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // limit each IP to 100 requests per windowMs
  message: { error: 'Too many requests from this IP' },
  standardHeaders: true,
  legacyHeaders: false,
});
app.use(limiter);

// Stricter rate limit for auth endpoints
const authLimiter = rateLimit({
  windowMs: 60 * 60 * 1000, // 1 hour
  max: 5, // 5 attempts per hour
  message: { error: 'Too many login attempts, please try again later' },
  skipSuccessfulRequests: true
});

// Body parsing with size limits
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ extended: true, limit: '10kb' }));

// Compression
app.use(compression());

// ==================== LOGGING ====================

const logger = winston.createLogger({
  level: process.env.LOG_LEVEL || 'info',
  format: winston.format.combine(
    winston.format.timestamp(),
    winston.format.json()
  ),
  transports: [
    new winston.transports.File({ filename: 'logs/error.log', level: 'error' }),
    new winston.transports.File({ filename: 'logs/security.log', level: 'warn' }),
    new winston.transports.File({ filename: 'logs/combined.log' })
  ],
  exceptionHandlers: [
    new winston.transports.File({ filename: 'logs/exceptions.log' })
  ]
});

if (process.env.NODE_ENV !== 'production') {
  logger.add(new winston.transports.Console({
    format: winston.format.simple()
  }));
}

// HTTP request logging
app.use(morgan('combined', {
  skip: (req, res) => res.statusCode < 400,
  stream: { write: message => logger.warn(message.trim()) }
}));

// Security event logger
const logSecurityEvent = (event, details, ip) => {
  logger.warn({
    type: 'SECURITY_EVENT',
    event,
    details,
    ip,
    timestamp: new Date().toISOString()
  });
};

// ==================== INPUT VALIDATION ====================

// XSS detection middleware
app.use((req, res, next) => {
  const suspiciousPatterns = [
    /<script/i,
    /javascript:/i,
    /on\w+\s*=/i,
    /<iframe/i,
    /eval\s*\(/i
  ];

  const queryString = JSON.stringify(req.query);
  const bodyString = JSON.stringify(req.body);

  if (suspiciousPatterns.some(p => 
    p.test(queryString) || p.test(bodyString))) {
    logSecurityEvent('XSS_ATTEMPT', {
      path: req.path,
      query: req.query,
      body: req.body
    }, req.ip);
    return res.status(400).json({ error: 'Invalid input detected' });
  }
  next();
});

// ==================== AUTHENTICATION MIDDLEWARE ====================

// Example JWT authentication middleware
const authMiddleware = (req, res, next) => {
  const token = req.headers.authorization?.split(' ')[1];

  if (!token) {
    logSecurityEvent('AUTH_MISSING_TOKEN', { path: req.path }, req.ip);
    return res.status(401).json({ error: 'Authorization token required' });
  }

  try {
    // Import jwt when implementing: const jwt = require('jsonwebtoken');
    // const decoded = jwt.verify(token, process.env.JWT_SECRET);
    // req.user = decoded;
    next();
  } catch (err) {
    logSecurityEvent('AUTH_INVALID_TOKEN', { path: req.path, error: err.message }, req.ip);
    return res.status(403).json({ error: 'Invalid or expired token' });
  }
};

// Authorization middleware - role-based access control
const requireRole = (role) => {
  return (req, res, next) => {
    if (!req.user) {
      return res.status(401).json({ error: 'Authentication required' });
    }

    if (req.user.role !== role && req.user.role !== 'admin') {
      logSecurityEvent('AUTH_UNAUTHORIZED_ACCESS', {
        path: req.path,
        userId: req.user.id,
        userRole: req.user.role,
        requiredRole: role
      }, req.ip);
      return res.status(403).json({ error: 'Insufficient permissions' });
    }

    next();
  };
};

// ==================== ROUTES ====================

// Health check with enhanced information
app.get('/health', async (req, res) => {
  const healthCheck = {
    status: 'ok',
    timestamp: new Date().toISOString(),
    uptime: process.uptime(),
    memory: process.memoryUsage(),
    environment: process.env.NODE_ENV || 'development',
    version: process.env.APP_VERSION || '1.0.0'
  };

  res.json(healthCheck);
});

// Users endpoint - protected and with pagination
app.get('/users', authMiddleware, requireRole('admin'), async (req, res) => {
  try {
    // Validate query parameters
    const page = Math.max(1, parseInt(req.query.page) || 1);
    const limit = Math.min(100, Math.max(1, parseInt(req.query.limit) || 10));

    // Example data - in production, fetch from database
    const users = [
      { id: 1, name: 'Alice' },  // Emails removed for security
      { id: 2, name: 'Bob' },
    ];

    // Log access to sensitive endpoint
    logger.info({
      type: 'ACCESS_LOG',
      endpoint: '/users',
      userId: req.user?.id,
      ip: req.ip,
      timestamp: new Date().toISOString()
    });

    res.json({
      data: users,
      pagination: {
        page,
        limit,
        total: users.length
      }
    });
  } catch (err) {
    logger.error('Error fetching users', { error: err.message });
    res.status(500).json({ error: 'Failed to fetch users' });
  }
});

// Example of secure POST endpoint
app.post('/users', [
  authMiddleware,
  requireRole('admin'),
  body('name').trim().isLength({ min: 1, max: 100 }).escape()
    .withMessage('Name must be 1-100 characters'),
  body('email').isEmail().normalizeEmail()
    .withMessage('Valid email required'),
  body('role').optional().isIn(['user', 'admin'])
    .withMessage('Role must be either "user" or "admin"')
], async (req, res) => {
  const errors = validationResult(req);

  if (!errors.isEmpty()) {
    logSecurityEvent('VALIDATION_ERROR', {
      path: req.path,
      errors: errors.array()
    }, req.ip);
    return res.status(400).json({ errors: errors.array() });
  }

  try {
    // Create user in database
    // ...

    logger.info({
      type: 'USER_CREATED',
      adminId: req.user.id,
      userEmail: req.body.email
    });

    res.status(201).json({ 
      message: 'User created successfully',
      // Never return passwords or sensitive data
    });
  } catch (err) {
    logger.error('Error creating user', { error: err.message });
    res.status(500).json({ error: 'Failed to create user' });
  }
});

// ==================== ERROR HANDLING ====================

// 404 handler
app.use((req, res) => {
  res.status(404).json({ 
    error: 'Not found',
    path: req.path 
  });
});

// Global error handler
app.use((err, req, res, next) => {
  // Log error
  logger.error({
    type: 'ERROR',
    message: err.message,
    stack: err.stack,
    url: req.url,
    method: req.method,
    ip: req.ip,
    timestamp: new Date().toISOString()
  });

  // Don't expose stack traces in production
  const isDevelopment = process.env.NODE_ENV !== 'production';

  res.status(err.status || 500).json({
    error: {
      message: isDevelopment ? err.message : 'Internal server error',
      ...(isDevelopment && { stack: err.stack })
    }
  });
});

// ==================== SERVER STARTUP ====================

const PORT = process.env.PORT || 3000;

const server = app.listen(PORT, () => {
  console.log(`Server running on port ${PORT}`);
  console.log(`Environment: ${process.env.NODE_ENV || 'development'}`);
});

// Graceful shutdown
const gracefulShutdown = (signal) => {
  console.log(`Received ${signal}. Starting graceful shutdown...`);

  server.close(() => {
    console.log('HTTP server closed');
    process.exit(0);
  });

  // Force shutdown after 10 seconds
  setTimeout(() => {
    console.error('Forced shutdown after timeout');
    process.exit(1);
  }, 10000);
};

process.on('SIGTERM', () => gracefulShutdown('SIGTERM'));
process.on('SIGINT', () => gracefulShutdown('SIGINT'));

module.exports = app;

