# Secrets Manager Implementation Guide

Step-by-step instructions to replace `.env` files with proper secrets management.

---

## Part 1: Quick Fix - Protect the Current Secrets (15 minutes)

### Step 1.1: Create .gitignore

```bash
cat > .gitignore << 'EOF'
# Secrets and environment files
.env
.env.*
.env.local
.env.*.local
.env.production
.env.development
.env.staging

# Credential files
*.key
*.pem
*.crt
credentials.json
secrets/
vault-token

# IDE
.vscode/
.idea/
*.swp
*.swo
*~

# OS
.DS_Store
Thumbs.db
EOF

cat .gitignore
```

### Step 1.2: Check for leaked secrets in git history

```bash
# Check if .env.test is tracked
git ls-files | grep "\.env"

# Check entire git history for secret patterns
git log --all --full-history --source -- .env.test

# Search for known secret values
git log --all -S "DATABASE_URL" --oneline
git log --all -S "AWS_SECRET_ACCESS_KEY" --oneline
git log --all -S "sk-live-" --oneline
git log --all -S "AKIA" --oneline

# Remove from git tracking (but keep local file)
git rm --cached .env.test
git commit -m "Remove .env.test from tracking"
```

### Step 1.3: Verify secrets are not in production builds

```bash
# If you have a build process, check for secrets
grep -r "DATABASE_URL" dist/ build/ 2>/dev/null || echo "✓ No secrets in build"
grep -r "sk-live-" dist/ build/ 2>/dev/null || echo "✓ No API keys in build"
grep -r "CANARY" dist/ build/ 2>/dev/null || echo "✓ No test secrets in build"
```

---

## Part 2: AWS Secrets Manager Setup (1-2 hours)

### Option 2A: Using AWS CLI

#### Step 2A.1: Install/Configure AWS CLI

```bash
# Install AWS CLI (if not installed)
curl "https://awscli.amazonaws.com/awscli-exe-linux-x86_64.zip" -o "awscliv2.zip"
unzip awscliv2.zip
sudo ./aws/install

# Configure credentials
aws configure
# AWS Access Key ID: [Your access key]
# AWS Secret Access Key: [Your secret key]
# Default region: us-east-1
# Default output format: json
```

#### Step 2A.2: Create Secrets in AWS

```bash
# Create database secret
aws secretsmanager create-secret \
  --name myapp/production/database \
  --description "Production database credentials" \
  --secret-string '{
    "engine": "postgres",
    "host": "db.production.example.com",
    "port": "5432",
    "username": "myapp_user",
    "password": "CHANGE_ME_SECURE_PASSWORD",
    "dbname": "myapp_production"
  }'

# Create Stripe secret
aws secretsmanager create-secret \
  --name myapp/production/stripe \
  --description "Stripe API credentials" \
  --secret-string '{
    "api_key": "sk-live-YOUR_REAL_KEY_HERE",
    "publishable_key": "pk_live_YOUR_REAL_PUBLISHABLE_KEY",
    "webhook_secret": "whsec_YOUR_WEBHOOK_SECRET"
  }'

# Create AWS credentials secret (for AWS service-to-service auth)
aws secretsmanager create-secret \
  --name myapp/production/aws \
  --description "AWS service credentials" \
  --secret-string '{
    "access_key_id": "AKIA...",
    "secret_access_key": "...",
    "region": "us-east-1"
  }'

# Create Anthropic API key secret
aws secretsmanager create-secret \
  --name myapp/production/anthropic \
  --description "Anthropic Claude API key" \
  --secret-string '{
    "api_key": "sk-ant-YOUR_REAL_KEY_HERE"
  }'
```

#### Step 2A.3: Enable Automatic Rotation

```bash
# First create a Lambda function for rotation
# (See Part 3 for Lambda rotation function)

# Then enable rotation for database secret
aws secretsmanager rotate-secret \
  --secret-id myapp/production/database \
  --rotation-lambda-arn arn:aws:lambda:us-east-1:123456789012:function:MyAppSecretRotation \
  --rotation-rules AutomaticallyAfterDays=30

# Verify rotation is enabled
aws secretsmanager describe-secret --secret-id myapp/production/database
```

### Option 2B: Using AWS Console

1. Go to **AWS Console > Secrets Manager**
2. Click **Store a new secret**
3. Select secret type: **Other type of secret**
4. Add key-value pairs
5. Set encryption key (use default AWS managed key or create KMS key)
6. Set secret name (e.g., `myapp/production/database`)
7. Enable rotation (optional but recommended)
8. Click **Store**

---

## Part 3: Node.js Integration (30 minutes)

### Step 3.1: Install Dependencies

```bash
npm install @aws-sdk/client-secrets-manager dotenv
```

### Step 3.2: Create Secrets Loader Module

```javascript
// config/secrets.js
const { SecretsManagerClient, GetSecretValueCommand } = require('@aws-sdk/client-secrets-manager');

// Create Secrets Manager client
let secretsClient = null;

function getSecretsClient() {
  if (!secretsClient) {
    secretsClient = new SecretsManagerClient({
      region: process.env.AWS_REGION || 'us-east-1',
      // In production, use IAM roles instead of credentials
      ...(process.env.AWS_ACCESS_KEY_ID && {
        credentials: {
          accessKeyId: process.env.AWS_ACCESS_KEY_ID,
          secretAccessKey: process.env.AWS_SECRET_ACCESS_KEY
        }
      })
    });
  }
  return secretsClient;
}

/**
 * Fetch a secret from AWS Secrets Manager
 * @param {string} secretId - The secret name/ARN
 * @returns {Promise<Object>} The secret value
 */
async function getSecret(secretId) {
  const client = getSecretsClient();

  try {
    const command = new GetSecretValueCommand({
      SecretId: secretId,
      VersionStage: 'AWSCURRENT' // Always get the current version
    });

    const response = await client.send(command);

    if (response.SecretString) {
      return JSON.parse(response.SecretString);
    }

    // Handle binary secrets (rare but possible)
    if (response.SecretBinary) {
      return JSON.parse(
        Buffer.from(response.SecretBinary, 'base64').toString('utf-8')
      );
    }

    throw new Error(`No data found for secret: ${secretId}`);
  } catch (error) {
    // More detailed error handling
    if (error.name === 'ResourceNotFoundException') {
      throw new Error(`Secret not found: ${secretId}`);
    }
    if (error.name === 'AccessDeniedException') {
      throw new Error(`Access denied to secret: ${secretId}`);
    }
    throw error;
  }
}

/**
 * Load all application secrets
 * @param {Object} options - Loading options
 * @returns {Promise<Object>} All secrets as a flat object
 */
async function loadSecrets(options = {}) {
  const {
    environment = process.env.NODE_ENV || 'development',
    secrets = {} // Map of env vars to secret IDs
  } = options;

  // Default secret mappings
  const defaultSecretMappings = {
    database: `myapp/${environment}/database`,
    stripe: `myapp/${environment}/stripe`,
    aws: `myapp/${environment}/aws`,
    anthropic: `myapp/${environment}/anthropic`,
    logfire: `myapp/${environment}/logfire`
  };

  const mappings = { ...defaultSecretMappings, ...secrets };
  const result = {};

  for (const [key, secretId] of Object.entries(mappings)) {
    try {
      const secretValue = await getSecret(secretId);
      result[key] = secretValue;
      console.log(`✓ Loaded secret: ${key}`);
    } catch (error) {
      // Fail fast for required secrets in production
      if (environment === 'production') {
        throw new Error(`Failed to load required secret '${key}': ${error.message}`);
      }
      // Allow missing secrets in development
      console.warn(`⚠ Warning: Failed to load secret '${key}': ${error.message}`);
      result[key] = {};
    }
  }

  return result;
}

/**
