## Part 4: Secret Rotation Lambda (1 hour)

### Step 4.1: Create Rotation Lambda Function

```javascript
// lambda/rotate-secret.js

const { SecretsManagerClient, RotateSecretCommand, GetSecretValueCommand, PutSecretValueCommand } = require('@aws-sdk/client-secrets-manager');
const { Client } = require('pg');

const secretsManager = new SecretsManagerClient({ region: process.env.AWS_REGION });

/**
 * Generate a random password
 */
function generatePassword(length = 32) {
  const chars = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789!@#$%^&*/()-+=';
  let password = '';
  const array = new Uint32Array(length);
  crypto.getRandomValues(array);
  for (let i = 0; i < length; i++) {
    password += chars[array[i] % chars.length];
  }
  return password;
}

/**
 * Connect to database
 */
async function connectToDatabase(secret) {
  const client = new Client({
    connectionString: `postgres://${secret.username}:${secret.password}@${secret.host}:${secret.port}/${secret.dbname}`
  });
  await client.connect();
  return client;
}

/**
 * Rotate database password
 */
async function rotateDatabasePassword(secretId) {
  // Step 1: Get current secret
  let response = await secretsManager.send(
    new GetSecretValueCommand({ SecretId: secretId })
  );
  let currentSecret = JSON.parse(response.SecretString);

  // Step 2: Generate new password
  const newPassword = generatePassword();

  // Step 3: Connect to database and change password
  const dbClient = await connectToDatabase(currentSecret);

  try {
    await dbClient.query(
      `ALTER USER "${currentSecret.username}" PASSWORD '${newPassword}'`
    );
  } finally {
    await dbClient.end();
  }

  // Step 4: Update secret with new password
  const newSecret = { ...currentSecret, password: newPassword };
  await secretsManager.send(
    new PutSecretValueCommand({
      SecretId: secretId,
      SecretString: JSON.stringify(newSecret)
    })
  );

  console.log(`✅ Rotated password for ${secretId}`);
}

// Lambda handler
exports.handler = async (event, context) => {
  console.log('Rotation event:', JSON.stringify(event, null, 2));

  const secretId = event.SecretId;

  try {
    await rotateDatabasePassword(secretId);

    return {
      statusCode: 200,
      body: JSON.stringify({ message: 'Secret rotated successfully' })
    };
  } catch (error) {
    console.error('Rotation failed:', error);
    throw error;
  }
};
```

