### Step 6.2: Create Pre-Commit Hook

```bash
cat > .husky/pre-commit << 'EOF'
#!/bin/sh
. "$(dirname "$0")/_/husky.sh"

# Check for secrets in staged files
echo "🔍 Checking for secrets..."

# Patterns to detect
SECRETS_PATTERNS=(
  "DATABASE_URL="
  "AWS_SECRET_ACCESS_KEY="
  "AWS_ACCESS_KEY_ID="
  "STRIPE_SECRET_KEY="
  "ANHTHROPIC_API_KEY="
  "sk-live-"
  "AKIA[A-Z0-9]{16}"
  "-----BEGIN.*PRIVATE KEY-----"
)

# Get staged files
STAGED_FILES=$(git diff --cached --name-only --diff-filter=ACM | grep '\.js$' | tr '\n' ' ')

if [ -z "$STAGED_FILES" ]; then
  echo "✓ No JS files staged"
  exit 0
fi

# Check each pattern
FOUND_SECRET=0
for pattern in "${SECRETS_PATTERNS[@]}"; do
  if git diff --cached | grep -qE "$pattern"; then
    echo "❌ Found potential secret matching pattern: $pattern"
    FOUND_SECRET=1
  fi
done

if [ $FOUND_SECRET -eq 1 ]; then
  echo "❌ Commit blocked: Potential secrets detected!"
  echo "❌ Please remove secrets or use placeholder values."
  exit 1
fi

echo "✓ No secrets detected"

# Run tests
npm test

# Run linter
npm run lint
EOF

chmod +x .husky/pre-commit
```

