/**
 * Secrets Management Module
 *
 * Handles loading secrets from appropriate sources based on environment:
 * - Development: .env files
 * - Staging/Production: AWS Systems Manager Parameter Store
 *
 * SECURITY: Never commit this file with hardcoded secrets!
 */

const { SSMClient, GetParameterCommand } = require('@aws-sdk/client-ssm');

// ============================================
// CONFIGURATION
// ============================================

const CONFIG = {
  // AWS Parameter Store path prefix
  parameterPrefix: `/myapp/${process.env.NODE_ENV || 'development'}`,

  // Cache TTL in milliseconds (5 minutes)
  cacheTTL: 5 * 60 * 1000,

  // Required secrets - application will fail without these
  requiredSecrets: [
    'JWT_SECRET',
    'DATABASE_URL',
  ],

  // Optional secrets with default values
  optionalSecrets: {
    AWS_ACCESS_KEY_ID: '',
    AWS_SECRET_ACCESS_KEY: '',
    AWS_REGION: 'us-east-1',
    ANTHROPIC_API_KEY: '',
    STRIPE_SECRET_KEY: '',
    LOGFIRE_TOKEN: '',
  }
};

// ============================================
// STATE
// ============================================

let secretsCache = {};
let cacheExpiry = null;
let ssmClient = null;

// ============================================
// INITIALIZATION
// ============================================

/**
 * Initialize secrets manager based on environment
 */
function initialize() {
  const env = process.env.NODE_ENV || 'development';

  console.log(`🔐 Initializing secrets management for ${env} environment`);

  // Only use AWS Parameter Store in staging/production
  if (env === 'staging' || env === 'production') {
    try {
      ssmClient = new SSMClient({
        region: process.env.AWS_REGION || CONFIG.optionalSecrets.AWS_REGION,
      });
      console.log('✅ AWS Parameter Store client initialized');
    } catch (error) {
      console.error('❌ Failed to initialize AWS SSM client:', error.message);
      throw error;
    }
  } else {
    console.log('ℹ️  Using environment variables for secrets (development mode)');
  }
}

// ============================================
// SECRET RETRIEVAL
// ============================================

/**
 * Fetch a single secret value
 * 
 * @param {string} secretName - Name of the secret (without path prefix)
 * @param {boolean} forceRefresh - Bypass cache and fetch fresh value
 * @returns {Promise<string>} Secret value
 */
async function getSecret(secretName, forceRefresh = false) {
  const env = process.env.NODE_ENV || 'development';

  // Check cache first (unless force refresh)
  if (!forceRefresh && secretsCache[secretName] && cacheExpiry && Date.now() < cacheExpiry) {
    console.debug(`📦 Cache hit for secret: ${secretName}`);
    return secretsCache[secretName];
  }

  // Development: Use environment variables
  if (env === 'development') {
    const value = process.env[secretName];

    if (!value) {
      // Check if there's a default value
      const defaultValue = CONFIG.optionalSecrets[secretName];
      if (defaultValue !== undefined) {
        console.warn(`⚠️  Using default value for optional secret: ${secretName}`);
        return defaultValue;
      }

      throw new Error(
        `Missing required secret: ${secretName}\n` +
        `Define it in your .env file: ${secretName}=your_value_here`
      );
    }

    // Cache it
    secretsCache[secretName] = value;
    cacheExpiry = Date.now() + CONFIG.cacheTTL;

    return value;
  }

  // Staging/Production: Fetch from AWS Parameter Store
  if (ssmClient) {
    try {
      const parameterName = `${CONFIG.parameterPrefix}/${secretName}`;

      console.debug(`🔍 Fetching from Parameter Store: ${parameterName}`);

      const command = new GetParameterCommand({
        Name: parameterName,
        WithDecryption: true, // Decrypt SecureString parameters
      });

      const response = await ssmClient.send(command);
      const value = response.Parameter.Value;

      if (!value) {
        throw new Error(`Parameter ${parameterName} exists but has no value`);
      }

      // Cache the result
      secretsCache[secretName] = value;
      cacheExpiry = Date.now() + CONFIG.cacheTTL;

      console.debug(`✅ Loaded secret: ${secretName}`);
      return value;

    } catch (error) {
      // Handle specific AWS errors
      if (error.name === 'ParameterNotFound') {
        throw new Error(
          `Secret not found in AWS Parameter Store: ${secretName}\n` +
          `Create it with: aws ssm put-parameter --name "${CONFIG.parameterPrefix}/${secretName}" --value "..." --type "SecureString"`
        );
      }

      // Log full error in development, generic in production
      if (env === 'development') {
        console.error('Error fetching secret:', error);
      }

      throw new Error(`Failed to fetch secret ${secretName}: ${error.message}`);
    }
  }

  throw new Error(`Cannot load secret ${secretName}: no secrets manager configured for ${env}`);
}

/**
 * Fetch all required secrets at once
 * 
 * @param {boolean} forceRefresh - Bypass cache
 * @returns {Promise<Object>} Object with all secrets
 */
async function loadAllSecrets(forceRefresh = false) {
  console.log('🔐 Loading secrets...');

  const secrets = {};
  const errors = [];

  // Load required secrets
  for (const secretName of CONFIG.requiredSecrets) {
    try {
      secrets[secretName] = await getSecret(secretName, forceRefresh);
    } catch (error) {
      errors.push({ secret: secretName, error: error.message });
    }
  }

  // Load optional secrets
  for (const secretName of Object.keys(CONFIG.optionalSecrets)) {
    try {
      secrets[secretName] = await getSecret(secretName, forceRefresh);
    } catch (error) {
      // Optional secrets shouldn't fail startup
      console.warn(`⚠️  Failed to load optional secret ${secretName}: ${error.message}`);
      secrets[secretName] = CONFIG.optionalSecrets[secretName];
    }
  }

  // Check if required secrets loaded successfully
  if (errors.length > 0) {
    const errorMsg = `Failed to load required secrets:\n${errors.map(e => `- ${e.secret}: ${e.error}`).join('\n')}`;
    console.error('❌ ' + errorMsg);
    throw new Error(errorMsg);
  }

  console.log(`✅ Successfully loaded ${Object.keys(secrets).length} secrets`);
  return secrets;
}

// ============================================
// CACHE MANAGEMENT
// ============================================

/**
 * Clear all cached secrets
 * Useful after secret rotation or for testing
 */
function clearCache() {
  console.log('🗑️  Clearing secrets cache');
  secretsCache = {};
  cacheExpiry = null;
}

/**
 * Get cache status (for debugging)
 */
function getCacheStatus() {
  return {
    keys: Object.keys(secretsCache),
    expiry: cacheExpiry,
    isExpired: cacheExpiry ? Date.now() >= cacheExpiry : true,
    ttl: cacheExpiry ? Math.max(0, cacheExpiry - Date.now()) : 0,
  };
}

// ============================================
// VALIDATION
// ============================================

/**
 * Validate that a secret meets minimum requirements
 * 
 * @param {string} secretName - Name of secret
 * @param {string} value - Secret value to validate
 * @returns {Object} Validation result
 */
function validateSecret(secretName, value) {
  const errors = [];

  // JWT secret should be at least 32 characters
  if (secretName === 'JWT_SECRET' && value.length < 32) {
    errors.push('JWT_SECRET must be at least 32 characters');
  }

  // Database URL should be a valid connection string
  if (secretName === 'DATABASE_URL' && !value.match(/^postgresql:\/\//i)) {
    errors.push('DATABASE_URL must be a valid PostgreSQL connection string');
  }

  return {
    valid: errors.length === 0,
    errors,
  };
}

/**
 * Validate all loaded secrets
 */
function validateAllSecrets(secrets) {
  const allErrors = [];

  for (const [name, value] of Object.entries(secrets)) {
    const result = validateSecret(name, value);
    if (!result.valid) {
      allErrors.push({ secret: name, errors: result.errors });
    }
  }

  return {
    valid: allErrors.length === 0,
    errors: allErrors,
  };
}

// ============================================
// EXPORTS
// ============================================

module.exports = {
  initialize,
  getSecret,
  loadAllSecrets,
  clearCache,
  getCacheStatus,
  validateSecret,
  validateAllSecrets,

  // Export config for testing
  CONFIG,
};

/**
 * Configuration Module
 * 
 * Centralizes all configuration loading from:
 * - Environment variables
 * - Secrets manager (via secrets.js)
 * - Default values
 */

require('dotenv').config(); // Load .env file in development

const secrets = require('./secrets');

// ============================================
// CONFIGURATION
// ============================================

/**
 * Load all configuration
 */
async function loadConfig() {
  // Initialize secrets manager
  secrets.initialize();

  // Load all secrets
  const secretValues = await secrets.loadAllSecrets();

  // Validate secrets
  const validation = secrets.validateAllSecrets(secretValues);
  if (!validation.valid) {
    console.error('❌ Secret validation failed:');
    validation.errors.forEach(err => {
      console.error(`  - ${err.secret}: ${err.errors.join(', ')}`);
    });
    throw new Error('Secret validation failed');
  }

  // Build complete configuration object
  const config = {
    // Application config
    app: {
      name: 'myapp',
      version: '1.0.0',
      env: process.env.NODE_ENV || 'development',
      port: parseInt(process.env.PORT) || 3000,
      debug: process.env.NODE_ENV === 'development',
    },

    // Security config (secrets)
    secrets: {
      jwt: secretValues.JWT_SECRET,
      database: secretValues.DATABASE_URL,
      aws: {
        accessKeyId: secretValues.AWS_ACCESS_KEY_ID,
        secretAccessKey: secretValues.AWS_SECRET_ACCESS_KEY,
        region: secretValues.AWS_REGION || 'us-east-1',
      },
      apiKeys: {
        anthropic: secretValues.ANTHROPIC_API_KEY,
        stripe: secretValues.STRIPE_SECRET_KEY,
        logfire: secretValues.LOGFIRE_TOKEN,
      },
    },

    // CORS config
    cors: {
      allowedOrigins: process.env.ALLOWED_ORIGINS?.split(',') || ['http://localhost:3000'],
      credentials: true,
    },

    // Rate limiting
    rateLimit: {
      windowMs: 15 * 60 * 1000, // 15 minutes
      max: 100, // requests per window
      strictMax: 10, // for sensitive endpoints
    },

    // Logging
    logging: {
      level: process.env.LOG_LEVEL || (process.env.NODE_ENV === 'production' ? 'info' : 'debug'),
      securityEvents: true,
    },
  };

  // Mask secrets in logs
  if (config.app.debug) {
    console.log('📋 Configuration loaded:');
    console.log(JSON.stringify({
      ...config,
      secrets: '[HIDDEN]' // Don't log secrets!
    }, null, 2));
  } else {
    console.log(`✅ Configuration loaded for ${config.app.env} environment`);
  }

  return config;
}

/**
 * Get a specific configuration value
 * Supports dot notation: 'app.port', 'secrets.jwt', etc.
 */
function get(key) {
  const keys = key.split('.');
  let value = config;

  for (const k of keys) {
    value = value?.[k];
    if (value === undefined) {
      return undefined;
    }
  }

  return value;
}

// Global config instance (singleton)
let config = null;

module.exports = {
  loadConfig,
  get,
  secrets, // Expose secrets module for direct access if needed
};

// Secure Express Application with Secrets Management
// Implements OWASP Top 10 security best practices

const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const cors = require('cors');
const morgan = require('morgan');
const { body, param, validationResult } = require('express-validator');
const jwt = require('jsonwebtoken');
const config = require('./config');

// ============================================
// APPLICATION INITIALIZATION
// ============================================

let appConfig;

// Initialize config before creating app
async function initializeApp() {
  try {
    console.log('🚀 Initializing application...');
    appConfig = await config.loadConfig();

    // Create Express app after config is loaded
    createExpressApp();

    return app;
  } catch (error) {
    console.error('❌ Failed to initialize application:', error.message);
    process.exit(1);
  }
}

function createExpressApp() {
  const app = express();

  const { app: appConf, secrets, cors: corsConf, rateLimit: rateLimitConf } = appConfig;

  // ============================================
  // SECURITY MIDDLEWARE
  // ============================================

  // 1. Security Headers using Helmet
  app.use(helmet({
    contentSecurityPolicy: {
      directives: {
        defaultSrc: ["'self'"],
        styleSrc: ["'self'", "'unsafe-inline'"],
        scriptSrc: ["'self'"],
        imgSrc: ["'self'", "data:", "https:"],
        connectSrc: ["'self'"],
        fontSrc: ["'self'"],
        objectSrc: ["'none'"],
        mediaSrc: ["'self'"],
        frameSrc: ["'none'"],
      },
    },
    hsts: {
      maxAge: 31536000, // 1 year
      includeSubDomains: true,
      preload: true
    },
    noSniff: true,
    frameguard: { action: 'deny' },
    xssFilter: true,
    referrerPolicy: { policy: 'strict-origin-when-cross-origin' },
  }));

  // 2. CORS Configuration
  app.use(cors({
    origin: (origin, callback) => {
      // Allow requests with no origin (like mobile apps, curl, etc)
      if (!origin) return callback(null, true);

      if (corsConf.allowedOrigins.includes(origin)) {
        callback(null, true);
      } else {
        logSecurityEvent('CORS_BLOCKED', { origin, path: null });
        callback(new Error('Not allowed by CORS'));
      }
    },
    credentials: true,
    methods: ['GET', 'POST', 'PUT', 'DELETE', 'OPTIONS'],
    allowedHeaders: ['Content-Type', 'Authorization', 'X-Requested-With'],
    exposedHeaders: ['X-Total-Count'],
    maxAge: 600 // 10 minutes
  }));

  // 3. Body Parser with Size Limits
  app.use(express.json({ 
    limit: '10kb',
    strict: true
  }));
  app.use(express.urlencoded({ 
    extended: true, 
    limit: '10kb' 
  }));

  // 4. Request Logging
  app.use(morgan(appConf.env === 'production' ? 'combined' : 'dev'));

  // 5. Rate Limiting
  const limiter = rateLimit({
    windowMs: rateLimitConf.windowMs,
    max: rateLimitConf.max,
    message: { error: 'Too many requests, please try again later.' },
    standardHeaders: true,
    legacyHeaders: false,
    handler: (req, res) => {
      logSecurityEvent('RATE_LIMIT_EXCEEDED', { ip: req.ip, path: req.path });
      res.status(429).json({ 
        error: 'Too many requests',
        retryAfter: Math.floor(rateLimitConf.windowMs / 1000)
      });
    }
  });

  const strictLimiter = rateLimit({
    windowMs: rateLimitConf.windowMs,
    max: rateLimitConf.strictMax,
    message: { error: 'Too many requests to this endpoint' }
  });

  app.use('/api', limiter);

  // ============================================
  // SECURITY UTILITIES
  // ============================================

  // Input Validation Middleware
  const validateRequest = (req, res, next) => {
    const errors = validationResult(req);
    if (!errors.isEmpty()) {
      logSecurityEvent('VALIDATION_FAILED', { 
        errors: errors.array(), 
        ip: req.ip, 
        path: req.path 
      });
      return res.status(400).json({ 
        error: 'Validation failed',
        details: errors.array() 
      });
    }
    next();
  };

  // Security Event Logger
  const logSecurityEvent = (eventType, details) => {
    const timestamp = new Date().toISOString();
    const logEntry = {
      timestamp,
      environment: appConf.env,
      eventType,
      ...details
    };

    if (appConf.debug) {
      console.warn('🔒 SECURITY_EVENT:', JSON.stringify(logEntry));
    } else {
      console.warn('SECURITY_EVENT:', JSON.stringify(logEntry));
      // TODO: Send to SIEM/monitoring service in production
    }
  };

  // Authentication Middleware (NOW IMPLEMENTED!)
  const authenticateToken = (req, res, next) => {
    const authHeader = req.headers['authorization'];
    const token = authHeader && authHeader.split(' ')[1];

    if (!token) {
      logSecurityEvent('AUTH_MISSING_TOKEN', { ip: req.ip, path: req.path });
      return res.status(401).json({ error: 'Access token required' });
    }

    // Verify token using secret from secrets manager
    jwt.verify(token, secrets.jwt, (err, user) => {
      if (err) {
        logSecurityEvent('AUTH_INVALID_TOKEN', { 
          ip: req.ip, 
          path: req.path,
          error: err.message 
        });
        return res.status(403).json({ error: 'Invalid or expired token' });
      }
      req.user = user;
      next();
    });
  };

  // Authorization Middleware
  const requireRole = (roles) => {
    return (req, res, next) => {
      if (!req.user || !roles.includes(req.user.role)) {
        logSecurityEvent('AUTH_UNAUTHORIZED', { 
          ip: req.ip, 
          path: req.path,
          userId: req.user?.id,
          userRole: req.user?.role,
          requiredRoles: roles 
        });
        return res.status(403).json({ error: 'Insufficient permissions' });
      }
      next();
    };
  };

  // Sanitize user data before sending
  const sanitizeUser = (user) => {
    const { id, name, email } = user;
    return { id, name, email };
  };

  // ============================================
  // ROUTES
  // ============================================

  // Health Check Endpoint (no auth required)
  app.get('/health', (req, res) => {
    res.json({ 
      status: 'ok', 
      timestamp: new Date().toISOString(),
      version: appConf.version,
      environment: appConf.env
    });
  });

  // API v1 Routes
  const apiV1 = express.Router();

  // Public endpoints (no authentication)
  apiV1.get('/public/info', (req, res) => {
    res.json({ message: 'Public information' });
  });

  // Protected endpoints (require authentication)
  apiV1.get('/users', strictLimiter, authenticateToken, requireRole(['admin']), (req, res) => {
    // In production, fetch from database with proper query
    const users = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ].map(sanitizeUser);

    res.json({
      data: users,
      count: users.length
    });

    logSecurityEvent('USERS_ACCESSED', { 
      userId: req.user?.id, 
      ip: req.ip,
      count: users.length
    });
  });

  // Get user by ID with input validation
  apiV1.get('/users/:id',
    strictLimiter,
    authenticateToken,
    param('id').isInt({ min: 1 }).withMessage('ID must be a positive integer'),
    validateRequest,
    (req, res) => {
      const userId = parseInt(req.params.id);

      // In production, fetch from database
      const user = { id: userId, name: 'Alice', email: 'alice@example.com' };

      res.json(sanitizeUser(user));

      logSecurityEvent('USER_ACCESSED', { 
        userId: req.user?.id,
        targetUserId: userId,
        ip: req.ip
      });
    }
  );

  // Example POST endpoint with validation
  apiV1.post('/users',
    authenticateToken,
