    await loadSecrets();

    // Validate secrets
    const required = ['DATABASE_URL', 'ANTHROPIC_API_KEY', 'STRIPE_SECRET_KEY'];
    const missing = required.filter(key => !process.env[key]);

    if (missing.length) {
      throw new Error(`Missing secrets: ${missing.join(', ')}`);
    }

    // Start application
    require('./server');
  } catch (error) {
    console.error('Failed to initialize:', error.message);
    process.exit(1);
  }
})();
