### Solution 5: Secrets Rotation Support

**Implement automatic secret rotation:**

```javascript
const crypto = require('crypto');

class SecretRotator {
  constructor(secretsManager, interval = 24 * 60 * 60 * 1000) {
    this.secretsManager = secretsManager;
    this.interval = interval;
    this.timers = new Map();
  }

  // Rotate a specific secret
  async rotateSecret(secretName, rotateCallback) {
    try {
      const newSecret = await rotateCallback();
      await this.secretsManager.updateSecret(secretName, newSecret);
      console.log(`✅ Rotated secret: ${secretName}`);

      // Reload in memory without restart
      process.env[secretName] = newSecret;
    } catch (error) {
      console.error(`❌ Failed to rotate secret ${secretName}:`, error.message);
    }
  }

  // Schedule automatic rotation
  scheduleRotation(secretName, interval, rotateCallback) {
    if (this.timers.has(secretName)) {
      clearInterval(this.timers.get(secretName));
    }

    const timer = setInterval(() => {
      this.rotateSecret(secretName, rotateCallback);
    }, interval);

    this.timers.set(secretName, timer);
    console.log(`🔄 Scheduled rotation for ${secretName} every ${interval}ms`);
  }

  // Stop all rotations
  stopAll() {
    this.timers.forEach((timer, secretName) => {
      clearInterval(timer);
      console.log(`⏹️ Stopped rotation for ${secretName}`);
    });
    this.timers.clear();
  }
}

// Usage example
const rotator = new SecretRotator(secretsManager);

rotator.scheduleRotation('DATABASE_URL', 30 * 24 * 60 * 60 * 1000, async () => {
  // Generate new database password
  const newPassword = crypto.randomBytes(32).toString('base64');
  // Update database and return new connection string
  return `postgres://admin:${newPassword}@db.internal:5432/production`;
});
```

