### Option 2: AWS Secrets Manager (Production)

```javascript
// config/secretManager.js - Production secrets loader
const AWS = require('aws-sdk');
const { SecretsManagerClient, GetSecretValueCommand } = require('@aws-sdk/client-secrets-manager');

class SecretsManager {
  constructor() {
    this.client = new SecretsManagerClient({
      region: process.env.AWS_REGION || 'us-east-1'
    });
    this.cache = new Map();
    this.cacheTTL = 5 * 60 * 1000; // 5 minutes
  }

  async getSecret(secretName) {
    // Check cache first
    const cached = this.cache.get(secretName);
    if (cached && Date.now() - cached.timestamp < this.cacheTTL) {
      return cached.value;
    }

    try {
      const command = new GetSecretValueCommand({
        SecretId: secretName
      });

      const response = await this.client.send(command);

      let secret;
      if (response.SecretString) {
        secret = JSON.parse(response.SecretString);
      } else {
        secret = Buffer.from(response.SecretBinary, 'base64').toString('utf-8');
      }

      // Cache the result
      this.cache.set(secretName, {
        value: secret,
        timestamp: Date.now()
      });

      return secret;
    } catch (error) {
      if (error.name === 'ResourceNotFoundException') {
        throw new Error(`Secret not found: ${secretName}`);
      }
      throw new Error(`Failed to fetch secret: ${error.message}`);
    }
  }

  async loadAllSecrets() {
    const secretNames = [
      `${process.env.NODE_ENV}/app/database`,
      `${process.env.NODE_ENV}/app/aws`,
      `${process.env.NODE_ENV}/app/api-keys`
    ];

    const secrets = {};

    for (const name of secretNames) {
      try {
        const [category, type] = name.split('/').slice(-2);
        secrets[category] = secrets[category] || {};
        secrets[category][type] = await this.getSecret(name);
      } catch (error) {
        console.warn(`Warning: Could not load secret ${name}`);
      }
    }

    return secrets;
  }
}

module.exports = new SecretsManager();
```

