```javascript
// config/secrets.js
const AWS = require('aws-sdk');
const { SecretsManagerClient, GetSecretValueCommand } = require('@aws-sdk/client-secrets-manager');

class SecretsManager {
  constructor() {
    this.client = new SecretsManagerClient({
      region: process.env.AWS_REGION || 'us-east-1'
    });
    this.cache = {};
    this.cacheTimeout = 300000; // 5 minutes
  }

  async getSecret(secretName, forceRefresh = false) {
    // Check cache first (unless forced refresh)
    if (!forceRefresh && this.cache[secretName]) {
      const cached = this.cache[secretName];
      if (Date.now() - cached.timestamp < this.cacheTimeout) {
        return cached.value;
      }
    }

    try {
      const command = new GetSecretValueCommand({
        SecretId: secretName
      });

      const response = await this.client.send(command);
      let secretString;

      if ('SecretString' in response) {
        secretString = response.SecretString;
      } else {
        secretString = Buffer.from(response.SecretBinary, 'base64').toString('utf-8');
      }

      const secretValue = JSON.parse(secretString);

      // Cache the secret
      this.cache[secretName] = {
        value: secretValue,
        timestamp: Date.now()
      };

      return secretValue;

    } catch (error) {
      if (error.name === 'ResourceNotFoundException') {
        throw new Error(`Secret not found: ${secretName}`);
      }
      throw error;
    }
  }

  async loadAllSecrets() {
    const secrets = await this.getSecret('production/app-secrets');

    // Set environment variables
    process.env.DATABASE_URL = secrets.DATABASE_URL;
    process.env.AWS_ACCESS_KEY_ID = secrets.AWS_ACCESS_KEY_ID;
    process.env.AWS_SECRET_ACCESS_KEY = secrets.AWS_SECRET_ACCESS_KEY;
    process.env.ANTHROPIC_API_KEY = secrets.ANTHROPIC_API_KEY;
    process.env.STRIPE_SECRET_KEY = secrets.STRIPE_SECRET_KEY;
    process.env.LOGFIRE_TOKEN = secrets.LOGFIRE_TOKEN;
    process.env.JWT_SECRET = secrets.JWT_SECRET;

    return secrets;
  }
}

const secretsManager = new SecretsManager();

module.exports = secretsManager;
```

