// config.js - Secure configuration loading
const { SecretsManagerClient, GetSecretValueCommand } = require('@aws-sdk/client-secrets-manager');
require('dotenv').config({ path: '.env.local' }); // Only for local development

class SecretManager {
  constructor() {
    this.client = process.env.NODE_ENV === 'production' 
      ? new SecretsManagerClient({ region: process.env.AWS_REGION })
      : null;
    this.cache = {};
    this.cacheTTL = 5 * 60 * 1000; // 5 minutes
  }

  async getSecret(name) {
    // Check cache first
    if (this.cache[name] && this.cache[name].expires > Date.now()) {
      return this.cache[name].value;
    }

    // Development: use environment variables
    if (process.env.NODE_ENV !== 'production') {
      const value = process.env[name];
      if (!value) {
        throw new Error(`Missing required secret: ${name}`);
      }
      return value;
    }

    // Production: fetch from AWS Secrets Manager
    try {
      const secretId = `${process.env.APP_NAME}/${process.env.NODE_ENV}/${name.toLowerCase()}`;
      const response = await this.client.send(
        new GetSecretValueCommand({ SecretId: secretId })
      );

      const secret = JSON.parse(response.SecretString);

      // Cache with TTL
      this.cache[name] = {
        value: secret[name] || secret.value || secret,
        expires: Date.now() + this.cacheTTL
      };

      return this.cache[name].value;
    } catch (error) {
      console.error(`Failed to fetch secret ${name}:`, error);
      throw new Error(`Secret fetch failed: ${name}`);
    }
  }
}

const secretManager = new SecretManager();

// Export a promise-based config
