## Complete Secure Implementation Example

Here's a completely refactored, secure version of `app.js`:

```javascript
// Secure Express.js Application
require('dotenv').config();

const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const cors = require('cors');
const { body, query, param, validationResult } = require('express-validator');
const jwt = require('jsonwebtoken');
const bcrypt = require('bcryptjs');
const morgan = require('morgan');
const { createLogger, format, transports } = require('winston');

const app = express();

// ============ SECURITY MIDDLEWARE ============

// Security headers
app.use(helmet({
  contentSecurityPolicy: {
    directives: {
      defaultSrc: ["'self'"],
      styleSrc: ["'self'", "'unsafe-inline'"],
      scriptSrc: ["'self'"],
      imgSrc: ["'self'", "data:", "https:"],
    },
  },
  hsts: {
    maxAge: 31536000,
    includeSubDomains: true,
    preload: true
  }
}));

app.disable('x-powered-by');

// CORS
app.use(cors({
  origin: process.env.ALLOWED_ORIGINS?.split(',') || [],
  methods: ['GET', 'POST', 'PUT', 'DELETE'],
  allowedHeaders: ['Content-Type', 'Authorization'],
  credentials: true,
  maxAge: 86400
}));

// Rate limiting
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 100,
  message: 'Too many requests',
  standardHeaders: true,
  legacyHeaders: false,
});
app.use(limiter);

// Body parsing with limits
app.use(express.json({ limit: '10kb', strict: true }));
app.use(express.urlencoded({ extended: true, limit: '10kb', parameterLimit: 100 }));

// Logging
const logger = createLogger({
  level: 'info',
  format: format.combine(format.timestamp(), format.json()),
  transports: [
    new transports.Console(),
    new transports.File({ filename: 'error.log', level: 'error' }),
    new transports.File({ filename: 'combined.log' })
  ]
});

app.use(morgan('combined', {
  stream: { write: msg => logger.info(msg.trim()) }
}));

// Security event logger
const logSecurityEvent = (event, details = {}) => {
  logger.warn({
    type: 'SECURITY_EVENT',
    event,
    timestamp: new Date().toISOString(),
    ...details
  });
};

// ============ VALIDATION MIDDLEWARE ============

const handleValidationErrors = (req, res, next) => {
  const errors = validationResult(req);
  if (!errors.isEmpty()) {
    logSecurityEvent('VALIDATION_FAILED', { errors: errors.array() });
    return res.status(400).json({ errors: errors.array() });
  }
  next();
};

// ============ AUTHENTICATION MIDDLEWARE ============

const authenticateToken = (req, res, next) => {
  const authHeader = req.headers['authorization'];
  const token = authHeader && authHeader.split(' ')[1];

  if (!token) {
    logSecurityEvent('AUTH_MISSING_TOKEN', { ip: req.ip });
    return res.status(401).json({ error: 'Access token required' });
  }

  jwt.verify(token, process.env.JWT_SECRET, (err, user) => {
    if (err) {
      logSecurityEvent('AUTH_INVALID_TOKEN', { ip: req.ip, error: err.message });
      return res.status(403).json({ error: 'Invalid or expired token' });
    }
    req.user = user;
    next();
  });
};

const authorize = (...roles) => (req, res, next) => {
  if (!roles.includes(req.user?.role)) {
    logSecurityEvent('AUTH_UNAUTHORIZED', { 
      ip: req.ip, 
      user: req.user?.id, 
      requiredRoles: roles 
    });
    return res.status(403).json({ error: 'Insufficient permissions' });
  }
  next();
};

// ============ ROUTES ============

app.get('/health', (req, res) => {
  res.json({ status: 'ok' });
});

// Protected users endpoint
app.get('/users', 
  authenticateToken, 
  authorize('admin'),
  handleValidationErrors,
  (req, res) => {
    const users = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ];
    res.json(users);
  }
);

// User lookup with ID validation
app.get('/users/:id',
  authenticateToken,
  param('id').isInt({ min: 1 }).toInt(),
  handleValidationErrors,
  (req, res) => {
    // Authorization: only admin or own user
    if (req.user.role !== 'admin' && req.user.id !== req.params.id) {
      logSecurityEvent('IDOR_ATTEMPT', { 
        userId: req.user.id, 
        targetId: req.params.id 
      });
      return res.status(403).json({ error: 'Access denied' });
    }

    const users = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ];

    const user = users.find(u => u.id === parseInt(req.params.id));
    if (!user) return res.status(404).json({ error: 'User not found' });

    res.json(user);
  }
);

// ============ ERROR HANDLING ============

app.use((req, res) => {
  res.status(404).json({ error: 'Endpoint not found' });
});

app.use((err, req, res, next) => {
  logger.error({
    error: err.message,
    stack: process.env.NODE_ENV === 'development' ? err.stack : undefined,
    url: req.url,
    method: req.method,
    ip: req.ip
  });

  const statusCode = err.statusCode || 500;
  res.status(statusCode).json({
    error: process.env.NODE_ENV === 'production' 
      ? 'An error occurred' 
      : err.message
  });
});

// ============ SERVER STARTUP ============

const requiredEnvVars = ['JWT_SECRET'];
requiredEnvVars.forEach(envVar => {
  if (!process.env[envVar]) {
    throw new Error(`Missing required environment variable: ${envVar}`);
  }
});

const PORT = process.env.PORT || 3000;
app.listen(PORT, () => {
  logger.info(`Server running on port ${PORT}`);
});

module.exports = app;
```

