### ✅ **Implement Proper Secrets Loading**

Here's a secure secrets loading pattern:

```javascript
// config/secrets.js
require('dotenv').config();

class SecretsManager {
  constructor() {
    this.cache = new Map();
    this.activeSource = null;
  }

  // Priority order for loading secrets
  async loadSecret(key) {
    // 1. Check cache
    if (this.cache.has(key)) {
      return this.cache.get(key);
    }

    // 2. Check environment variables (runtime)
    const envValue = process.env[key];
    if (envValue && envValue !== 'undefined') {
      this.activeSource = 'environment';
      this.cache.set(key, envValue);
      return envValue;
    }

    // 3. Check cloud secrets manager (production)
    if (this.isProduction()) {
      const cloudValue = await this.loadFromCloud(key);
      if (cloudValue) {
        this.activeSource = 'cloud_manager';
        this.cache.set(key, cloudValue);
        return cloudValue;
      }
    }

    // 4. Check local .env file (development only)
    if (!this.isProduction()) {
      if (!process.env[key]) {
        // dotenv already loaded, but we check again
        throw new Error(`Secret ${key} not found and not in production`);
      }
    }

    throw new Error(`Secret ${key} not found`);
  }

  async loadFromCloud(key) {
    // AWS Secrets Manager integration
    const AWS = require('aws-sdk');
    const client = new AWS.SecretsManager({ region: process.env.AWS_REGION || 'us-east-1' });

    try {
      const secretName = `${process.env.APP_NAME}/${key}`;
      const data = await client.getSecretValue({ SecretId: secretName }).promise();

      if ('SecretString' in data) {
        return JSON.parse(data.SecretString)[key];
      }

      return Buffer.from(data.SecretBinary, 'base64').toString();
    } catch (error) {
      console.error(`Failed to load ${key} from AWS Secrets Manager:`, error.message);
      return null;
    }
  }

  isProduction() {
    return process.env.NODE_ENV === 'production';
  }

  // Log secret source for security audit
  logSecretSource() {
    console.log(`[Security] Secrets loaded from: ${this.activeSource}`);
  }
}

module.exports = new SecretsManager();
```

