### ✅ **Environment-Specific Secret Loading**

```javascript
// config/env.js
const path = require('path');
const dotenv = require('dotenv');

const envFiles = {
  development: '.env.development',
  test: '.env.test',
  staging: '.env.staging',
  production: '.env.production'
};

function loadEnvironment() {
  const env = process.env.NODE_ENV || 'development';
  const envFile = envFiles[env];

  if (envFile) {
    const result = dotenv.config({ path: path.resolve(process.cwd(), envFile) });

    if (result.error) {
      if (env === 'production') {
        throw new Error(`Failed to load production .env file: ${result.error.message}`);
      } else {
        console.warn(`Warning: ${envFile} not found, using defaults`);
      }
    } else {
      console.warn(`⚠️  Loaded secrets from file: ${envFile}`);
    }
  }

  // Validate required secrets
  const required = {
    development: [],
    test: [],
    staging: ['DATABASE_URL', 'JWT_SECRET'],
    production: ['DATABASE_URL', 'JWT_SECRET', 'AWS_REGION']
  };

  const missing = required[env] || [];
  for (const key of missing) {
    if (!process.env[key]) {
      throw new Error(`Missing required secret: ${key}`);
    }
  }

  return env;
}

module.exports = loadEnvironment();
