### ✅ **Secret Rotation Policy**

```javascript
// config/secret-rotator.js
const AWS = require('aws-sdk');
const crypto = require('crypto');

class SecretRotator {
  constructor() {
    this.secretsManager = new AWS.SecretsManager();
  }

  async rotateSecret(secretName) {
    const secret = await this.secretsManager.getSecretValue({
      SecretId: secretName
    }).promise();

    const currentSecret = JSON.parse(secret.SecretString);
    const newSecret = {
      ...currentSecret,
      password: crypto.randomBytes(32).toString('hex'),
      updatedAt: new Date().toISOString()
    };

    // Store previous version for rollback
    const previousVersion = {
      previous: currentSecret,
      current: newSecret
    };

    await this.secretsManager.updateSecret({
      SecretId: secretName,
      SecretString: JSON.stringify(previousVersion)
    }).promise();

    console.log(`🔄 Rotated secret: ${secretName}`);
    return newSecret;
  }

  async rollbackSecret(secretName) {
    const secret = await this.secretsManager.getSecretValue({
      SecretId: secretName
    }).promise();

    const data = JSON.parse(secret.SecretString);
    if (data.previous) {
      await this.secretsManager.updateSecret({
        SecretId: secretName,
        SecretString: JSON.stringify(data.previous)
      }).promise();
      console.log(`⏪ Rolled back secret: ${secretName}`);
    }
  }
}
```

